	command, err := sdkcli.Parse(args)
	if err != nil {
		return "", "", err
	}
	if _, ok := creators[command.Path]; !ok || !strings.HasSuffix(command.Path, " create") {
		return "", "", errors.New("OCI command is not a supported foundation create")
	}
	step, err := canonicalRequest(region, command)
	if err != nil {
		return "", "", err
	}
	sum := sha256.Sum256(step)
	if command.Path != "os bucket create" && command.Path != "os retention-rule create" {
		token = ociresource.RetryToken(ctx, string(step))
	}
	return hex.EncodeToString(sum[:]), token, nil
}

func canonicalRequest(region string, command sdkcli.Command) ([]byte, error) {
	flags := make(map[string]any, len(command.Flags))
	for key, value := range command.Flags {
		if key == "wait-for-state" {
			continue
		}
		flags[key] = value
		if strings.HasPrefix(value, "{") || strings.HasPrefix(value, "[") {
			payload := jsontext.Value(value)
			if err := payload.Format(jsontext.ReorderRawObjects(true)); err != nil {
				return nil, fmt.Errorf("invalid OCI %s payload", key)
			}
			flags[key] = payload
		}
	}
	step, err := json.Marshal(map[string]any{"region": region, "path": command.Path, "flags": flags}, json.Deterministic(true))
	if err != nil {
		return nil, errors.New("OCI retry identity is invalid")
	}
	return step, nil
}

func (c *SDKClient) identity() (identity.IdentityClient, error) {
	return c.reader.Factory().Identity()
}

func createCompartment(ctx context.Context, c *SDKClient, command sdkcli.Command) (any, error) {
	values, err := flags(command, "compartment-id", "name", "description")
	if err != nil {
		return nil, err
	}
	tags, err := optionalTags(command)
	if err != nil {
		return nil, err
	}
	client, err := c.identity()
	if err != nil {
		return nil, err
	}
	token, err := retryToken(ctx, c, command)
	if err != nil {
		return nil, err
	}
	response, err := client.CreateCompartment(ociclient.RequestContext(ctx), identity.CreateCompartmentRequest{OpcRetryToken: token,
		CreateCompartmentDetails: identity.CreateCompartmentDetails{FreeformTags: tags, CompartmentId: &values[0], Name: &values[1], Description: &values[2]}})
	return response.Compartment, err
}

func createPolicy(ctx context.Context, c *SDKClient, command sdkcli.Command) (any, error) {
	values, err := flags(command, "compartment-id", "name", "description")
	if err != nil {
		return nil, err
	}
	var statements []string
	if err := jsonFlag(command, "statements", &statements); err != nil {
		return nil, err
	}
	tags, err := optionalTags(command)
	if err != nil {
		return nil, err
	}
	client, err := c.identity()
	if err != nil {
		return nil, err
	}
	token, err := retryToken(ctx, c, command)
	if err != nil {
		return nil, err
	}
	response, err := client.CreatePolicy(ociclient.RequestContext(ctx), identity.CreatePolicyRequest{OpcRetryToken: token,
		CreatePolicyDetails: identity.CreatePolicyDetails{FreeformTags: tags, CompartmentId: &values[0], Name: &values[1], Description: &values[2], Statements: statements}})
	return response.Policy, err
}

func (c *Client) Call(ctx context.Context, args []string) (data jsontext.Value, handled bool, err error) {
	command, err := Parse(args)
	if err != nil {
		return nil, false, err
	}
	if _, ok := command.Flags["output"]; ok {
		return nil, false, errors.New("OCI --output is fixed to json")
	}
	if _, ok := command.Flags["region"]; ok {
		return nil, false, errors.New("OCI --region is selected by the caller")
	}
	handler, ok := handlers[command.Path]
	if !ok {
		return nil, false, fmt.Errorf("%w: %s", ErrUnsupported, command.Path)
	}
	value, err := handler(ociclient.RequestContext(ctx), c, command)
	if err != nil {
		return nil, true, fmt.Errorf("OCI read failed: %s: %w", command.Path, err)
	}
	if unused := command.unused(); len(unused) > 0 {
		// The read ignored a flag, so its result may be wider than asked
		// for. Report the command as unsupported rather than answer it.
		return nil, false, fmt.Errorf("%w: %s with --%s", ErrUnsupported, command.Path, strings.Join(unused, ", --"))
	}
	data, err = Render(value)
	return data, true, err
}

func iamCompartmentGet(ctx context.Context, c *Client, command Command) (any, error) {
	id, err := command.flag("compartment-id")
	if err != nil {
		return nil, err
	}
	client, err := c.identity()
	if err != nil {
		return nil, err
	}
	response, err := client.GetCompartment(ctx, identity.GetCompartmentRequest{CompartmentId: &id})
	return response.Compartment, err
}

func iamCompartmentList(ctx context.Context, c *Client, command Command) (any, error) {
	id, err := command.flag("compartment-id")
	if err != nil {
		return nil, err
	}
	client, err := c.identity()
	if err != nil {
		return nil, err
	}
	return pages(command.All, func(page *string) ([]identity.Compartment, *string, error) {
		response, err := client.ListCompartments(ctx, identity.ListCompartmentsRequest{CompartmentId: &id, Page: page})
		return response.Items, response.OpcNextPage, err
	})
}

