func (r *regionList) String() string { return strings.Join(*r, ",") }
func (r *regionList) Set(value string) error {
	for part := range strings.SplitSeq(value, ",") {
		if part = strings.TrimSpace(part); part != "" {
			*r = append(*r, part)
